mapper.select:
SELECT
	kbn_class_code AS kbnClassCode,
	kbn_code AS kbnCode,
	created_by AS createdBy,
	created_at AS createdAt,
	sort_order AS sortOrder,
	kbn_group_code AS kbnGroupCode,
	kbn_class_japanese_name AS kbnClassJapaneseName,
	kbn_group_japanese_name AS kbnGroupJapaneseName,
	kbn_japanese_name AS kbnJapaneseName,
	kbn_class_english_name AS kbnClassEnglishName,
	kbn_group_english_name AS kbnGroupEnglishName,
	kbn_english_name AS kbnEnglishName,
	explanation
FROM
	common.kbn_mst

	 AND kbn_class_code = #{kbnClassCode, typeHandler=com.web.gallery.type_handler.KbnClassCodeTypeHandler}
	 AND kbn_code = #{kbnCode, typeHandler=com.web.gallery.type_handler.KbnCodeTypeHandler}
	 AND sort_order = #{sortOrder, typeHandler=com.web.gallery.type_handler.SortOrderTypeHandler}
	AND kbn_group_code = #{kbnGroupCode, typeHandler=com.web.gallery.type_handler.KbnGroupCodeTypeHandler}
	 AND kbn_class_japanese_name = #{kbnClassJapaneseName, typeHandler=com.web.gallery.type_handler.KbnClassJapaneseNameTypeHandler}
	AND kbn_group_japanese_name = #{kbnGroupJapaneseName, typeHandler=com.web.gallery.type_handler.KbnGroupJapaneseNameTypeHandler}
	 AND kbn_japanese_name = #{kbnJapaneseName, typeHandler=com.web.gallery.type_handler.KbnJapaneseNameTypeHandler}
	 AND kbn_class_english_name = #{kbnClassEnglishName, typeHandler=com.web.gallery.type_handler.KbnClassEnglishNameTypeHandler}
	AND kbn_group_english_name = #{kbnGroupEnglishName, typeHandler=com.web.gallery.type_handler.KbnGroupEnglishNameTypeHandler}
	 AND kbn_english_name = #{kbnEnglishName, typeHandler=com.web.gallery.type_handler.KbnEnglishNameTypeHandler}
	 AND explanation = #{explanation, typeHandler=com.web.gallery.type_handler.ExplanationTypeHandler}
